const SCHEMA = { type: 'object', properties: {
  section: { type: 'string' },
  created: { type: 'array', items: { type: 'object', properties: { name: { type: 'string' }, id: { type: 'string' } }, required: ['name', 'id'] } },
  ledger: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, status: { type: 'string' }, note: { type: 'string' } }, required: ['id', 'status'] } },
  issues: { type: 'array', items: { type: 'string' } },
}, required: ['section', 'created', 'ledger', 'issues'] }
const keys = Array.isArray(args) ? args : []
phase('Screens')
const CONT = `CONTINUATION RUN: an earlier run of this slice was interrupted (Figma MCP tool-call limit or a container restart). PREPARED SCRIPTS: earlier agents saved ready-to-run, idempotent use_figma scripts under /home/user/Claude/design/figma-build/pending/<folder>/ (see README.md or RUN-ORDER.json; finished scripts usually in out/), /home/user/Claude/design/figma-build/pending-<slice>/ and /home/user/Claude/design/figma-build/queue/<slice>/. Find the folder(s) for your slice (by slice key or by your ledger row IDs, e.g. pending/adm-bc = ADM-B*/C*, pending/pub-04 = PUB-04, pending/pub-10-11-12-15 = PUB-10/11/12/15, pending/pub-16-17-19 = PUB-16/17/19, queue/usr-rg = USR-RG*). If found: read its README/RUN-ORDER, then run its assembled scripts in the given order by reading each file and passing its full content as the use_figma code (if a script fails, fix the cause in its source + rebuild per its README, or patch inline). Afterwards build anything still missing. Interrupted earlier run of this slice: FIRST make ONE read-only use_figma call per involved page that lists every top-level frame in your section(s) (names, ids, width, height) — do not use get_metadata/get_screenshot. Treat existing frames as done unless their name/size shows they are incomplete (e.g. height exactly 800 with clipped content → set primaryAxisSizingMode='AUTO'). Build ONLY the missing frames/states, batching 2–3 related frames per use_figma call, and verify with node.screenshot() at the end of each build script. Follow conventions §10 (limit rules) strictly; if the limit blocks you 3 times in a row, stop and report exactly which frames remain.`
const results = await parallel(keys.map(k0 => () => { const cont = k0.startsWith('cont:'); const k = cont ? k0.slice(5) : k0; return agent(COMMON + '\n\n' + (cont ? CONT + '\n\n' : '') + SPECS[k], { label: (cont ? 'cont:' : 'screens:') + k, phase: 'Screens', schema: SCHEMA }).then(r => ({ key: k, ...r })) }))
return results
